package com.lianxibu.site.repository.jobs;
import com.lianxibu.site.domain.jobs.CollectorNodeFacts;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.domain.protocol.WireValues;
import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.*;import org.springframework.transaction.support.*;
import tools.jackson.databind.JsonNode;import tools.jackson.databind.json.JsonMapper;
/** Complete current node, original bounded heartbeat and original creation receipt inside one owned read-only snapshot. */
public final class JdbcCollectorNodeFacts implements CollectorNodeFacts.Api {
 private final JdbcTemplate jdbc;private final JdbcCollectorHeartbeats heartbeats;private final TransactionTemplate reads;private final Clock clock;
 private static final Set<String> PERMISSIONS=Set.of("config:read","run:claim","run:read","run:write","observation:write","heartbeat:write","probe:claim","probe:write");
 public JdbcCollectorNodeFacts(DataSource source,PlatformTransactionManager tx,Clock clock){this.jdbc=new JdbcTemplate(Objects.requireNonNull(source));this.heartbeats=new JdbcCollectorHeartbeats(source);this.clock=Objects.requireNonNull(clock);reads=new TransactionTemplate(Objects.requireNonNull(tx));reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);reads.setTimeout(10);}
 @Override public CollectorNodeFacts.Evidence read(String node){
  if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("collector facts must own read-only snapshot");
  try{return reads.execute(status->acquire(node));}catch(RuntimeException unavailable){return null;}
 }
 private CollectorNodeFacts.Evidence acquire(String node){
  WireValues.id(node,false);var rows=jdbc.query("SELECT config_revision,enabled,last_seen_at,CASE WHEN OCTET_LENGTH(allowed_source_ids) BETWEEN 1 AND 65536 THEN allowed_source_ids ELSE NULL END,CASE WHEN OCTET_LENGTH(permissions_json) BETWEEN 1 AND 2048 THEN permissions_json ELSE NULL END FROM collector_nodes WHERE id=?",(r,n)->new Object[]{r.getLong(1),r.getInt(2),r.getTimestamp(3,utc()),r.getString(4),r.getString(5)},node);
  if(rows.size()!=1)throw unavailable();var row=rows.getFirst();long revision=(long)row[0];int enabled=(int)row[1];if(revision<1||revision>CanonicalJson.MAX_SAFE_INTEGER||enabled<0||enabled>1)throw unavailable();ids((String)row[3],1000,false);var permissions=ids((String)row[4],8,true);if(enabled==1&&!permissions.contains("heartbeat:write"))throw unavailable();
  var history=heartbeats.original(node);CollectorNodeFacts.Heartbeat snapshot=null;Instant baseline;
  if(history==null){if(row[2]!=null)throw unavailable();baseline=created(node);}
  else {if(history.nodeRevision()>revision||row[2]==null||!history.latest().receivedAt().equals(((java.sql.Timestamp)row[2]).toInstant()))throw unavailable();var entry=history.latest();var value=entry.input().sample();baseline=history.samples().getFirst().receivedAt();snapshot=new CollectorNodeFacts.Heartbeat(history.nodeRevision(),history.revision(),value.observedAt(),entry.receivedAt(),value.pendingObservations(),value.pendingControls(),value.quarantined(),value.outboxBytes(),value.freeBytes(),value.oldestPendingAt());}
  var pending=jdbc.query("SELECT id FROM source_runs WHERE (claim_node_id=? OR node_id=?) AND (delivery_state IS NULL OR delivery_state NOT IN ('complete','partial','no_usable_input','empty_success') OR pending_count IS NULL OR pending_count<>0 OR barrier_closed_at IS NULL OR result_json IS NULL OR manifest_hash IS NULL) ORDER BY id LIMIT 201",(r,n)->WireValues.id(r.getString(1),false),node,node);if(pending.size()>200)throw unavailable();
  Instant read=clock.instant().truncatedTo(ChronoUnit.MICROS);if(baseline==null||Thread.currentThread().isInterrupted())throw unavailable();return new CollectorNodeFacts.Evidence(node,revision,enabled==1,baseline,snapshot,pending.size(),read);
 }
 private Instant created(String node){
  var rows=jdbc.query("SELECT id,principal,actor_id,operation,request_key,key_hash,request_hash,status_code,expires_at,original_status,current_status,CASE WHEN OCTET_LENGTH(response_json) BETWEEN 1 AND 65536 THEN response_json ELSE NULL END,CASE WHEN OCTET_LENGTH(result_ref_json) BETWEEN 1 AND 4096 THEN result_ref_json ELSE NULL END,created_at FROM request_receipts WHERE receipt_kind='admin_action' AND scope='collector_nodes:create' AND result_ref_json LIKE ? ORDER BY id LIMIT 2",(r,n)->{
   String actor=WireValues.id(r.getString(3),false),key=r.getString(5);var at=r.getTimestamp(14,utc());var expiry=r.getTimestamp(9,utc());if(!actor.equals(r.getString(2))||!"collector_nodes:create".equals(r.getString(4))||key==null||!key.matches("[!-~]{1,128}")||!Arrays.equals(r.getBytes(6),digest(key))||r.getInt(8)!=200||!"applied".equals(r.getString(10))||!"applied".equals(r.getString(11))||at==null||expiry==null||!expiry.toInstant().equals(at.toInstant().plusSeconds(30L*86400))||r.getString(12)==null||r.getString(13)==null)throw unavailable();WireValues.id(r.getString(1),false);
   var refKeys=Set.of("node_id","action","revision");var ref=WireValues.object(CanonicalJson.parse(r.getString(13)),refKeys,refKeys);if(!node.equals(WireValues.id(ref.get("node_id"),false))||!"create".equals(WireValues.text(ref.get("action")))||WireValues.nonnegativeInteger(ref.get("revision"))!=1)throw unavailable();
   var resultKeys=Set.of("action","node");var result=WireValues.object(CanonicalJson.parse(r.getString(12)),resultKeys,resultKeys);var keys=Set.of("id","name","source_ids","permissions","revision","revoked","last_heartbeat_at");var original=WireValues.object(result.get("node"),keys,keys);
   String name=WireValues.text(original.get("name"));if(!"create".equals(WireValues.text(result.get("action")))||!node.equals(WireValues.id(original.get("id"),false))||name.isBlank()||name.codePointCount(0,name.length())>100||WireValues.nonnegativeInteger(original.get("revision"))!=1||!original.get("revoked").isBoolean()||original.get("revoked").booleanValue()||!original.get("last_heartbeat_at").isNull())throw unavailable();ids(original.get("source_ids").toString(),1000,false);ids(original.get("permissions").toString(),8,true);
   var command=JsonMapper.shared().createObjectNode();command.put("name",name);command.set("source_ids",original.get("source_ids"));command.set("permissions",original.get("permissions"));var input=JsonMapper.shared().createObjectNode();input.put("actor_id",actor);input.put("scope","collector_nodes:create");input.put("action","create");input.putNull("target");input.set("command",command);if(!Arrays.equals(r.getBytes(7),HexFormat.of().parseHex(CanonicalJson.hash(CanonicalJson.Domain.ACTION,input)))||jdbc.queryForObject("SELECT COUNT(*) FROM users WHERE id=?",Integer.class,actor)!=1)throw unavailable();return at.toInstant();
  },"%"+node+"%");if(rows.size()!=1)throw unavailable();return rows.getFirst();
 }
 private static List<String> ids(String raw,int limit,boolean permission){if(raw==null)throw unavailable();var value=CanonicalJson.parse(raw);if(!value.isArray()||value.size()>limit)throw unavailable();var result=new ArrayList<String>();for(var item:value){String id=WireValues.text(item);if(permission){if(!PERMISSIONS.contains(id))throw unavailable();}else WireValues.id(id,true);if(result.contains(id))throw unavailable();result.add(id);}return List.copyOf(result);}
 private static byte[] digest(String value){try{return java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(java.security.NoSuchAlgorithmException impossible){throw unavailable();}}
 private static Calendar utc(){return Calendar.getInstance(TimeZone.getTimeZone("UTC"));}
 private static IllegalStateException unavailable(){return new IllegalStateException("complete native collector node facts unavailable");}
}
